88   * htmlParseErr:
    89   * @ctxt:  an HTML parser context
    90   * @error:  the error number
    91   * @msg:  the error message
    92   * @str1:  string infor
    93   * @str2:  string infor
    94   *
    95   * Handle a fatal parser error, i.e. violating Well-Formedness constraints
    96   */
    97  static void LIBXML_ATTR_FORMAT(3,0)
    98  htmlParseErr(xmlParserCtxtPtr ctxt, xmlParserErrors error,
    99               const char *msg, const xmlChar *str1, const xmlChar *str2)
   100  {
   101      if ((ctxt != NULL) && (ctxt->disableSAX != 0) &&
   102          (ctxt->instate == XML_PARSER_EOF))
   103          return;
   104      if (ctxt != NULL)
   105          ctxt->errNo = error;
   106      __xmlRaiseError(NULL, NULL, NULL, ctxt, NULL, XML_FROM_HTML, error,
   107                      XML_ERR_ERROR, NULL, 0,
   108                      (const char *) str1, (const char *) str2,
   109                      NULL, 0, 0,
   110                      msg, str1, str2);
   111      if (ctxt != NULL)
   112          ctxt->wellFormed = 0;
   340   * buffer this is needed to try to switch to the proper encoding when
   341   * one face a character error.
   342   * That's an heuristic, since it's operating outside of parsing it could
   343   * try to use a meta which had been commented out, that's the reason it
   344   * should only be used in case of error, not as a default.
   345   *
   346   * Returns an encoding string or NULL if not found, the string need to
   347   *   be freed
   348   */
   349  static xmlChar *
   350  htmlFindEncoding(xmlParserCtxtPtr ctxt) {
   351      const xmlChar *start, *cur, *end;
   352
   353      if ((ctxt == NULL) || (ctxt->input == NULL) ||
   354          (ctxt->input->flags & XML_INPUT_HAS_ENCODING))
   355          return(NULL);
   356      if ((ctxt->input->cur == NULL) || (ctxt->input->end == NULL))
   357          return(NULL);
   358
   359      start = ctxt->input->cur;
   360      end = ctxt->input->end;
   361      /* we also expect the input buffer to be zero terminated */
   362      if (*end != 0)
   363          return(NULL);
   364
   365      cur = xmlStrcasestr(start, BAD_CAST "HTTP-EQUIV");
   366      if (cur == NULL)
   367          return(NULL);
   368      cur = xmlStrcasestr(cur, BAD_CAST  "CONTENT");
   369      if (cur == NULL)
   370          return(NULL);
   371      cur = xmlStrcasestr(cur, BAD_CAST  "CHARSET=");
   372      if (cur == NULL)
   373          return(NULL);
   374      cur += 8;
   375      start = cur;
   376      while (((*cur >= 'A') && (*cur <= 'Z')) ||
   377             ((*cur >= 'a') && (*cur <= 'z')) ||
   378             ((*cur >= '0') && (*cur <= '9')) ||
   379             (*cur == '-') || (*cur == '_') || (*cur == ':') || (*cur == '/'))
   380             cur++;
   381      if (cur == start)
   382          return(NULL);
   383      return(xmlStrndup(start, cur - start));
   384  }
